SELECT id, tupleElement(arrayJoin(samples) AS __sample, 1) AS timestamp, tupleElement(__sample, 2) AS value FROM (SELECT _CAST(id, 'Tuple(UInt64, LowCardinality(UUID))') AS id, _CAST(samples, 'Array(Tuple(DateTime64(3), Float64))') AS samples FROM (SELECT id, timeSeriesSliceSortedArray(samples, toDateTime64(toDecimal128('1000000', 3), 3), toDateTime64(toDecimal128('1000300', 3), 3)) AS samples FROM default.`.inner_id.samples.84d0bdc9-061b-4c11-9060-67d9bbb7234c` WHERE and(greaterOrEquals(bucket, toDateTime64(toDecimal128('997200', 3), 3)), lessOrEquals(bucket, toDateTime64(toDecimal128('1000300', 3), 3)), greaterOrEquals(max_time, toDateTime64(toDecimal128('1000000', 3), 3)), lessOrEquals(min_time, toDateTime64(toDecimal128('1000300', 3), 3)), in(id, (SELECT timeSeriesStoreTags(id, tags, '__name__', metric_name) FROM default.`.inner_id.tags.84d0bdc9-061b-4c11-9060-67d9bbb7234c` ALL LEFT JOIN (SELECT id, 1 AS matched FROM default.`.inner_id.timeranges.84d0bdc9-061b-4c11-9060-67d9bbb7234c` WHERE and(greaterOrEquals(max_time, toDateTime64(toDecimal128('1000000', 3), 3)), lessOrEquals(min_time, toDateTime64(toDecimal128('1000300', 3), 3)), in(id, (SELECT id FROM default.`.inner_id.tags.84d0bdc9-061b-4c11-9060-67d9bbb7234c` WHERE match(metric_name, '^m_1[0-9][0-9]$'))))) AS time_ranges_subquery USING (id) WHERE and(match(metric_name, '^m_1[0-9][0-9]$'), equals(time_ranges_subquery.matched, 1)))))) WHERE notEmpty(samples))